from pathlib import Path
from copy import deepcopy
import json,uuid,httpx
P=Path(__file__).resolve().parent;prep=json.loads((P/'preparation_queued.json').read_text())['job']['job_id'];c=httpx.Client(base_url='http://127.0.0.1:8000',timeout=60)
v=c.get('/api/jobs/'+prep).json();(P/'preparation_status.json').write_text(json.dumps(v,indent=2)+'\n');assert v['status'] in ['completed','failed'],v['status'];assert (v.get('result') or {}).get('projection_run_id') or 'preparation_result' in str(v)
r=c.post('/api/optimizer/preliminary/snapshots',json=dict(preparation_job_id=prep,injury_policy='exclude_unknown_and_questionable',analyst_mode='BASELINE'));(P/'snapshot_response.json').write_text(r.text+'\n');r.raise_for_status();f=r.json();old=json.loads((P/'old_request_capture.json').read_text())['rows'][0]['request_json'];request=deepcopy(old);request['snapshot_sha256']=f['snapshot_sha256'];opt=request['optimizer'];opt['projection_run_id']=f['projection_run_id'];opt['optimizer_run_id']=str(uuid.uuid4());opt['params']['football_news_evidence']=json.loads((P/'news_ingest.json').read_text());assert opt['params']['classic_selection_objective']=='baseline_mean';assert opt['params']['locked_player_ids']==[];assert opt['params']['locked_players']==[]
(P/'submitted_request.json').write_text(json.dumps(request,indent=2)+'\n');r=c.post('/api/optimizer/preliminary/jobs',json=request);(P/'optimizer_queued.json').write_text(r.text+'\n');r.raise_for_status();print(json.dumps(dict(snapshot=f['snapshot_sha256'],projection_run_id=f['projection_run_id'],ownership_run_id=f['ownership_run_id'],optimizer_run_id=opt['optimizer_run_id'],queue=r.json()),indent=2))
